func BinarySearch_explicit(values []int, target int) int {
	low := 0
	high := len(values) - 1
	for low <= high {
		middle := low + (high-low)/2
		switch {
		case values[middle] == target:
			return middle
		case values[middle] < target:
			low = middle + 1
		default:
			high = middle - 1
		}
	}
	return -1
}

